inputSchema:
{
  "title": "Input schema for Instagram reel scraper",
  "type": "object",
  "description": "To scrape reels, enter an <b>Instagram username or profile URL</b>. You can also paste <b>direct reel URLs</b>. Then click ▶ <b>Start</b> and the data will be extracted. The rest of the fields are optional. If you need help, follow this <a href='https://apify.it/3IQguuh' target='_blank' rel='noopener'>video tutorial</a>.<br><br>🎬 To extract reels that are <b>popular for a keyword</b>, use <a href='https://console.apify.com/actors/DrF9mzPPEuVizVF4l/input' target='_blank' rel='noopener'>Instagram Search Scraper</a>. To extract reels <b>by hashtag</b>, use <a href='https://console.apify.com/actors/reGe1ST3OBgYZSsZJ/input' target='_blank' rel='noopener'>Instagram Hashtag Scraper</a>. If you want to scrape comments from each reel, use <a href='https://console.apify.com/actors/SbK00X0JYCPblD2wp/input' target='_blank' rel='noopener'>Instagram Comments Scraper</a>.",
  "schemaVersion": 1,
  "properties": {
    "username": {
      "title": "🎞️ Instagram username, profile URL, ID, or reel URL",
      "type": "array",
      "description": "Add Instagram usernames, profile URLs, IDs, or direct reel URLs. Each item will be processed individually.",
      "editor": "stringList",
      "prefill": [
        "natgeo"
      ]
    },
    "resultsLimit": {
      "title": "💯 Maximum reels per profile",
      "type": "integer",
      "description": "Set how many reels should be scraped per profile. For example, if set to 5, the scraper will extract up to 5 reels from each profile. This setting is ignored when scraping direct reel URLs.",
      "editor": "number",
      "prefill": 25,
      "minimum": 1
    },
    "onlyPostsNewerThan": {
      "title": "📅 Scrape reels newer than",
      "type": "string",
      "description": "Scrape reels from the provided date up to the present. Supported formats include `YYYY-MM-DD`, full ISO timestamps (e.g. `2025-09-23T10:02:01`), or relative time such as `1 day`, `2 weeks`, or `3 months`. All times are evaluated in UTC.",
      "editor": "datepicker",
      "dateType": "absoluteOrRelative",
      "pattern": "^(\\d{4})-(0[1-9]|1[0-2])-(0[1-9]|[12]\\d|3[01])(T[0-2]\\d:[0-5]\\d(:[0-5]\\d)?(\\.\\d+)?Z?)?$|^(\\d+)\\s*(minute|hour|day|week|month|year)s?$",
      "sectionCaption": "Date range filter",
      "sectionDescription": "Limit scraping to reels published within a specific time period."
    },
    "skipPinnedPosts": {
      "title": "📌 Skip pinned reels",
      "type": "boolean",
      "description": "Enable this option if you want to exclude pinned reels from the overall results.",
      "default": false,
      "sectionCaption": "Exclude content",
      "sectionDescription": "Choose what to leave out of your results: pinned reels (often much older than the rest, so skipping them keeps results chronologically accurate) and <a href='https://creators.instagram.com/blog/instagram-trial-reels' target='_blank' rel='noopener'>trial reels</a> (videos creators test with non-followers before a wider release). <br><br> ℹ️  <a href='https://apify.com/apify/instagram-post-scraper#can-i-exclude-pinned-posts-even-if-they-are-within-the-date-range' target='_blank' rel='noopener'>Pinned reels & date range filter</a> <b>|</b> <a href='https://apify.com/apify/instagram-post-scraper#is-there-any-way-to-scrape-only-new-posts-including-pinned-ones-while-filtering-out-older-pinned-posts' target='_blank' rel='noopener'>Only new reels (including new pinned)</a>"
    },
    "skipTrialReels": {
      "title": "🎬 Skip trial reels",
      "type": "boolean",
      "description": "If enabled, the feed will be scraped without trial reels: an Instagram feature creators use to test a video with non-followers before sharing it with their existing audience. <a href='https://creators.instagram.com/blog/instagram-trial-reels' target='_blank' rel='noopener'>Learn more</a>.",
      "default": false
    },
    "includeSharesCount": {
      "title": "$ Include shares count",
      "type": "boolean",
      "description": "Extract the number of shares for each reel. Available for paying users only. Upgrade to the <a href='https://console.apify.com/billing/subscription' target='_blank' rel='noopener'>Starter plan</a> to unlock it.",
      "default": false,
      "sectionCaption": "Include transcript, download reels, or scrape number of shares",
      "sectionDescription": "Unlock advanced reel data and media features. Track shares alongside likes, comments, views, and play count, extract audio transcripts for large-scale content analysis, or download reel videos to secure a local copy before links expire. Note that these add-ons are billed separately based on usage and type of data."
    },
    "includeTranscript": {
      "title": "$ Include transcript",
      "type": "boolean",
      "description": "Extract a text transcript of the reel audio for content analysis. This <a href='https://apify.com/apify/instagram-reel-scraper/pricing' target='_blank' rel='noopener'>add-on feature</a> is charged per minute of audio.",
      "default": false
    },
    "includeDownloadedVideo": {
      "title": "$ Include downloaded video",
      "type": "boolean",
      "description": "Download the reel video and store a local copy before Instagram links expire. This <a href='https://apify.com/apify/instagram-reel-scraper/pricing' target='_blank' rel='noopener'>add-on feature</a> is charged per 1 MB downloaded.",
      "default": false
    }
  },
  "required": [
    "username"
  ]
}
